import type { EditorBase } from "./bs_main_catalogue";

export const validScopes = new Set([
  "force",
  "roster",
  "self",
  "parent",
  "ancestor",
  "primary-category",
  "force",
  "roster",
  "primary-catalogue",
  "root-entry", "unit", "model", "upgrade", "model-or-unit", "non-upgrade-entry", "group", "link"
]);
export const validChildIds = new Set(["any", "unit", "model", "upgrade", "mount", "crew"]);

// Entry-type scopes that accept an optional "-self" suffix: "<scope>-self" means the
// bearing node itself is a candidate (resolve via findParentOrSelf) instead of only its
// ancestors (findParent). Kept here so the editor and the app agree on the format.
// ponytail: root-entry omitted — NR resolves it self-inclusively already, so "root-entry-self" is a no-op.
// Add it back here if/when the app grows a findParent-only root-entry path.
export const selfableScopes = new Set([
  "group", "model", "upgrade", "non-upgrade-entry", "unit", "model-or-unit", "link",
]);
/** Split "<scope>-self" → { base, self:true }; otherwise { base:scope, self:false }. */
export function splitScopeSelf(scope: string): { base: string; self: boolean } {
  if (typeof scope === "string" && scope.endsWith("-self")) {
    const base = scope.slice(0, -"-self".length);
    if (selfableScopes.has(base)) return { base, self: true };
  }
  return { base: scope, self: false };
}

export function isScopeValid(parent: EditorBase, scope: string) {
  if (validScopes.has(splitScopeSelf(scope).base)) return true;
  const catalogue = parent.catalogue;
  const found = catalogue.findOptionById(scope);
  if (found) {
    if (found.isForce() && !parent.isForce()) return true;
    if (found.isCategory()) return true;
    if (found.isCatalogue()) return true;
  }
  const stack = [parent];
  while (stack.length) {
    const current = stack.pop()!;
    if (current.id === scope) return true;
    if (current.parent) stack.push(current.parent);
    if (current.refs) stack.push(...current.refs)
  }
  return false;
}
